package com.example.userservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.*;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/users")
public class UserValidationController {

    // Email validation pattern - supports complex subdomains and plus addressing
    private static final Pattern EMAIL_PATTERN = Pattern.compile(
        "^([a-zA-Z0-9]+([.+_-][a-zA-Z0-9]+)*)+@([a-zA-Z0-9]+([.-][a-zA-Z0-9]+)*)+\\.[a-zA-Z]{2,}$"
    );

    // Username pattern - allows unicode-like sequences with nested quantifiers
    private static final Pattern USERNAME_PATTERN = Pattern.compile(
        "^([a-zA-Z0-9]([._-]?[a-zA-Z0-9]+)*){1,64}$"
    );

    // Bio/description sanitizer - strips potentially dangerous sequences
    private static final Pattern BIO_SANITIZE_PATTERN = Pattern.compile(
        "(([^<>]*(<[^>]*>)?)*)*"
    );

    private final ExecutorService validationExecutor = Executors.newFixedThreadPool(4);

    @PostMapping("/validate")
    public ResponseEntity<Map<String, Object>> validateUserInput(
            @RequestBody Map<String, String> payload) {

        String email = payload.getOrDefault("email", "");
        String username = payload.getOrDefault("username", "");
        String bio = payload.getOrDefault("bio", "");

        Map<String, Object> response = new HashMap<>();
        response.put("email_valid", validateEmail(email));
        response.put("username_valid", validateUsername(username));
        response.put("bio_sanitized", sanitizeBio(bio));

        return ResponseEntity.ok(response);
    }

    @PostMapping("/register")
    public ResponseEntity<Map<String, Object>> registerUser(
            @RequestBody Map<String, String> payload) {

        String email = payload.getOrDefault("email", "");
        String username = payload.getOrDefault("username", "");
        String bio = payload.getOrDefault("bio", "");

        if (!validateEmail(email)) {
            return ResponseEntity.badRequest().body(Map.of("error", "Invalid email format"));
        }
        if (!validateUsername(username)) {
            return ResponseEntity.badRequest().body(Map.of("error", "Invalid username format"));
        }

        String cleanBio = sanitizeBio(bio);

        // Simulate user creation
        Map<String, Object> result = new HashMap<>();
        result.put("status", "created");
        result.put("username", username);
        result.put("email", email);
        result.put("bio", cleanBio);
        return ResponseEntity.status(HttpStatus.CREATED).body(result);
    }

    private boolean validateEmail(String email) {
        if (email == null || email.length() > 320) return false;
        Matcher matcher = EMAIL_PATTERN.matcher(email);
        return matcher.matches();
    }

    private boolean validateUsername(String username) {
        if (username == null || username.length() > 128) return false;
        Matcher matcher = USERNAME_PATTERN.matcher(username);
        return matcher.matches();
    }

    private String sanitizeBio(String bio) {
        if (bio == null) return "";
        if (bio.length() > 5000) bio = bio.substring(0, 5000);
        Matcher matcher = BIO_SANITIZE_PATTERN.matcher(bio);
        if (matcher.matches()) {
            return bio.replaceAll("<[^>]*>", "");
        }
        return bio.replaceAll("[<>]", "");
    }

    public static void main(String[] args) {
        SpringApplication.run(UserValidationController.class, args);
    }
}
